from collections import deque

def _norm(points):
    r0=min(r for r,c in points); c0=min(c for r,c in points)
    return frozenset((r-r0,c-c0) for r,c in points)

def _symmetries(points):
    out=set()
    for flip in (1,-1):
        for k in range(4):
            pts=[]
            for r,c in points:
                x,y=r,flip*c
                for _ in range(k): x,y=y,-x
                pts.append((x,y))
            out.add(_norm(pts))
    return out

def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                x,y=q.pop(); comp.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((color,comp))
    refs=[p for color,p in comps if color==8]
    if not refs: return [row[:] for row in grid]
    signatures=set()
    for pts in refs: signatures.update(_symmetries(pts))
    out=[row[:] for row in grid]
    for color,pts in comps:
        if color!=8 and _norm(pts) in signatures:
            for r,c in pts: out[r][c]=8
    return out
