def _norm(points):
    r0=min(r for r,c in points); c0=min(c for r,c in points)
    return frozenset((r-r0,c-c0) for r,c in points)

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                x,y=stack.pop(); pts.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); stack.append((nx,ny))
            comps.append((color,pts))
    # Match exact translated shapes; components with a target color provide the color key.
    keys={}
    for color,pts in comps:
        if color != 1:
            keys.setdefault(_norm(pts), color)
    out=[row[:] for row in grid]
    for color,pts in comps:
        if color==1:
            new=keys.get(_norm(pts))
            if new is not None:
                for r,c in pts: out[r][c]=new
    return out
